package org.eclipse.rdf4j.workbench.proxy.config;

import java.io.IOException;
import java.nio.charset.StandardCharsets;

import jakarta.servlet.http.HttpServletResponse;

/** Response helpers shared by the Workbench servlet and redirect filter policy checks. */
public final class WorkbenchPolicyResponse {
	private WorkbenchPolicyResponse() {
	}

	public static void sendHiddenPage(HttpServletResponse response) throws IOException {
		response.sendError(HttpServletResponse.SC_NOT_FOUND);
	}

	public static void sendDisabledLanding(HttpServletResponse response) throws IOException {
		sendDisabledLanding(response,
				"The RDF4J Workbench is disabled because all Workbench pages are hidden by policy.");
	}

	/**
	 * Answers a request while the Workbench policy is invalid: {@code 503 Service Unavailable} with the problem, so
	 * that the administrator sees it in the browser as well as in the log.
	 */
	public static void sendInvalidPolicy(HttpServletResponse response, InvalidWorkbenchPolicyException failure)
			throws IOException {
		response.setHeader("Cache-Control", "no-store");
		sendDisabledLanding(response, "The RDF4J Workbench is unavailable because its policy file "
				+ "workbench.properties is invalid: " + failure.getProblem() + System.lineSeparator()
				+ "Fix the file and restart the Workbench; the server log names the file.");
	}

	public static void sendDisabledLanding(HttpServletResponse response, String message) throws IOException {
		response.setStatus(HttpServletResponse.SC_SERVICE_UNAVAILABLE);
		response.setCharacterEncoding(StandardCharsets.UTF_8.name());
		response.setContentType("text/plain; charset=UTF-8");
		response.getWriter().println(message);
	}
}
